const QUESTIONS = [
  {
    id: "q1",
    text: "Which of the following are statically typed languages?",
    help: "Statically typed languages verify types at compile time, catching type errors before the program runs.",
    options: ["JavaScript", "TypeScript", "Java", "Python"],
    correct: new Set(["TypeScript", "Java"]),
  },
  {
    id: "q2",
    text: "Which languages are commonly used for systems programming?",
    options: ["Ruby", "C", "Rust", "HTML"],
    correct: new Set(["C", "Rust"]),
  },
  {
    id: "q3",
    text: "Which of the following languages use automatic garbage collection?",
    options: ["C", "Java", "Go", "Rust"],
    correct: new Set(["Java", "Go"]),
  },
];

function buildQuiz() {
  const form = document.getElementById("quiz-form");

  QUESTIONS.forEach((q, index) => {
    const field = document.createElement("div");
    field.className = "form-field";

    const fieldset = document.createElement("fieldset");
    const legendText = document.createElement("legend");
    legendText.textContent = q.text;

    fieldset.appendChild(legendText);

    if (q.help) {
      const help = document.createElement("span");
      help.className = "help-text";
      help.id = `${q.id}-help`;
      help.textContent = q.help;
      fieldset.appendChild(help);
      fieldset.setAttribute("aria-describedby", help.id);
    }

    const ol = document.createElement("ol");
    ol.className = "options";
    ol.setAttribute("role", "list");

    q.options.forEach((option) => {
      const li = document.createElement("li");

      const label = document.createElement("label");
      label.className = "option-label";

      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.name = q.id;
      checkbox.value = option;
      checkbox.id = `${q.id}-${option.replace(/\s+/g, "-").toLowerCase()}`;

      label.setAttribute("for", checkbox.id);
      label.appendChild(checkbox);
      label.appendChild(document.createTextNode(option));

      li.appendChild(label);
      ol.appendChild(li);
    });

    fieldset.appendChild(ol);
    field.appendChild(fieldset);

    // Insert before the submit wrapper
    const submitWrap = document.querySelector(".submit-wrap");
    form.insertBefore(field, submitWrap);
  });
}

function getSelections() {
  return QUESTIONS.map((q) => {
    const checked = form.querySelectorAll(`input[name="${q.id}"]:checked`);
    return new Set([...checked].map((cb) => cb.value));
  });
}

function scoreQuiz(selections) {
  let total = 0;
  selections.forEach((selected, i) => {
    const correct = QUESTIONS[i].correct;
    const isExact =
      selected.size === correct.size &&
      [...selected].every((v) => correct.has(v));
    if (isExact) total++;
  });
  return total;
}

function applyFeedback(selections) {
  QUESTIONS.forEach((q, i) => {
    const selected = selections[i];
    const labels = form.querySelectorAll(`input[name="${q.id}"]`);

    labels.forEach((cb) => {
      const label = cb.closest(".option-label");
      const isSelected = selected.has(cb.value);
      const isCorrect = q.correct.has(cb.value);

      label.classList.remove("correct", "wrong", "missed");

      const badge = document.createElement("span");
      badge.className = "option-badge";
      badge.setAttribute("aria-hidden", "true");

      if (isSelected && isCorrect) {
        label.classList.add("correct");
        badge.textContent = "✓";
        label.appendChild(badge);
      } else if (isSelected && !isCorrect) {
        label.classList.add("wrong");
        badge.textContent = "✗";
        label.appendChild(badge);
      } else if (!isSelected && isCorrect) {
        label.classList.add("missed");
        badge.textContent = "Missed";
        label.appendChild(badge);
      }
    });
  });
}

const form = document.getElementById("quiz-form");
const resultEl = document.getElementById("result");
const submitBtn = document.getElementById("submit-btn");

buildQuiz();

form.addEventListener("submit", (e) => {
  e.preventDefault();

  if (form.classList.contains("submitted")) return;

  const selections = getSelections();
  const score = scoreQuiz(selections);
  const total = QUESTIONS.length;

  applyFeedback(selections);
  form.classList.add("submitted");

  const passed = score === total;
  resultEl.className = `show ${passed ? "pass" : "fail"}`;
  resultEl.textContent = passed
    ? `🎉 Perfect score! You got all ${total} questions correct.`
    : `You got ${score} out of ${total} correct. Review the highlighted answers above.`;

  resultEl.setAttribute("role", "status");
  submitBtn.textContent = "Submitted";
  submitBtn.disabled = true;

  resultEl.focus();
});
